mkdir -p "$ROOT/app_ready_godot_cat_idle8/assets/sprites/cat" "$ROOT/app_ready_godot_cat_idle8/scenes" "$ROOT/app_ready_godot_cat_idle8/scripts" "$ROOT/app_ready_godot_cat_idle8/docs"
rsync -a "$ROOT/assets/sprites/cat/idle8" "$ROOT/app_ready_godot_cat_idle8/assets/sprites/cat/"
cp "$ROOT/assets/sprites/cat/idle8_sheet.png" "$ROOT/app_ready_godot_cat_idle8/assets/sprites/cat/"
cp "$ROOT/assets/sprites/cat/idle8_sheet.json" "$ROOT/app_ready_godot_cat_idle8/assets/sprites/cat/"
cp "$ROOT/scenes/cat_idle8.tscn" "$ROOT/app_ready_godot_cat_idle8/scenes/"
cp "$ROOT/scripts/cat_player.gd" "$ROOT/app_ready_godot_cat_idle8/scripts/"
cp "$ROOT/preview/cat-idle8-preview.png" "$ROOT/app_ready_godot_cat_idle8/docs/"
cp "$ROOT/app_ready_godot_cat_idle8/docs/APP_USAGE.md" "$ROOT/app_ready_godot_cat_idle8/docs/APP_USAGE.md" 2>/dev/null || true

cat > "$ROOT/app_ready_godot_cat_idle8/install_to_godot_project.sh" <<'GODOTSH'
#!/usr/bin/env bash
set -euo pipefail
if [ $# -ne 1 ]; then
  echo "Usage: $0 /absolute/path/to/your/godot/project"
  exit 1
fi
TARGET="$1"
PKG_DIR="$(cd "$(dirname "$0")" && pwd)"
mkdir -p "$TARGET/assets/sprites/cat" "$TARGET/scenes" "$TARGET/scripts"
rsync -a "$PKG_DIR/assets/sprites/cat/idle8" "$TARGET/assets/sprites/cat/"
cp "$PKG_DIR/assets/sprites/cat/idle8_sheet.png" "$TARGET/assets/sprites/cat/"
cp "$PKG_DIR/assets/sprites/cat/idle8_sheet.json" "$TARGET/assets/sprites/cat/"
cp "$PKG_DIR/scenes/cat_idle8.tscn" "$TARGET/scenes/"
cp "$PKG_DIR/scripts/cat_player.gd" "$TARGET/scripts/"
echo "Installed to $TARGET"
GODOTSH
chmod +x "$ROOT/app_ready_godot_cat_idle8/install_to_godot_project.sh"

# Unity package
rm -rf "$ROOT/app_ready_unity_cat_idle8"
UNITY_BASE="$ROOT/app_ready_unity_cat_idle8/Assets/CatIdle8"
mkdir -p "$UNITY_BASE/Resources/CatIdle8/idle8" "$UNITY_BASE/Scripts" "$ROOT/app_ready_unity_cat_idle8/docs"
rsync -a "$ROOT/assets/sprites/cat/idle8/" "$UNITY_BASE/Resources/CatIdle8/idle8/"
cp "$ROOT/preview/cat-idle8-preview.png" "$ROOT/app_ready_unity_cat_idle8/docs/"
cat > "$UNITY_BASE/Scripts/CatIdle8Player.cs" <<'CS'
using UnityEngine;

[RequireComponent(typeof(SpriteRenderer))]
public class CatIdle8Player : MonoBehaviour
{
    public float fps = 10f;
    private Sprite[] frames;
    private SpriteRenderer sr;
    private float timer;
    private int index;

    void Awake()
    {
        sr = GetComponent<SpriteRenderer>();
        frames = new Sprite[8];
        for (int i = 0; i < 8; i++)
        {
            string path = $"CatIdle8/idle8/{(i + 1).ToString("00")}";
            Texture2D tex = Resources.Load<Texture2D>(path);
            if (tex != null)
            {
                frames[i] = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 0f), 96f);
            }
        }
        if (frames[0] != null) sr.sprite = frames[0];
    }

    void Update()
    {
        if (frames == null || frames.Length == 0) return;
        timer += Time.deltaTime;
        float frameTime = 1f / Mathf.Max(1f, fps);
        if (timer >= frameTime)
        {
            timer -= frameTime;
            index = (index + 1) % frames.Length;
            if (frames[index] != null) sr.sprite = frames[index];
        }
    }
}
CS
cat > "$ROOT/app_ready_unity_cat_idle8/docs/APP_USAGE.md" <<'UNITYMD'
# Unity Cat Idle8 Quick Use

1. Copy the `Assets` folder into your Unity project root.
2. Create an empty GameObject, add `SpriteRenderer` and `CatIdle8Player`.
3. Press Play. The 8-frame idle loop plays at 10 FPS.
UNITYMD

